@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Outfit:wght@400;500;600;700;800&display=swap');
:root{--ink:#f7f2e7;--muted:#c7c9bd;--gold:#ffdf91;--glass:rgba(17,29,34,.55)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#192a32;color:var(--ink);font-family:'DM Sans',sans-serif;overscroll-behavior:none;touch-action:none}#game{position:relative;width:100%;height:100%;overflow:hidden;background:linear-gradient(#a9d8d1,#daf0d4)}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,30,36,.25),transparent 25%,transparent 72%,rgba(13,30,36,.18));z-index:1}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;padding:max(24px,env(safe-area-inset-top)) 34px 0;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.brand{display:flex;align-items:center;gap:12px;letter-spacing:.13em}.brand-mark{font-size:30px;color:#ffe6a5;text-shadow:0 0 18px #ffdc84}.brand b{font:700 14px Outfit,sans-serif;display:block;letter-spacing:.18em}.brand small,.objective small{display:block;color:#e4e6d9;font:600 9px 'DM Sans';letter-spacing:.22em;margin-top:3px}.objective{position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:12px;align-items:center;background:var(--glass);border:1px solid #ffffff25;border-radius:12px;padding:12px 18px;backdrop-filter:blur(12px);box-shadow:0 8px 30px #152c2e22;min-width:265px}.quest-icon{font-size:25px;color:var(--gold)}.objective small{font-size:8px;color:#f0d99c;margin:0 0 4px}.objective b{font:600 13px Outfit,sans-serif}.map-wrap{width:93px;height:93px;border:1px solid #f4edcf77;border-radius:50%;padding:5px;position:relative;background:rgba(21,39,39,.32);box-shadow:0 5px 25px #132a2530}.map-wrap canvas{width:100%;height:100%;border-radius:50%}.map-n{position:absolute;top:-9px;left:50%;transform:translateX(-50%);font:700 9px Outfit;color:#fff4d8}.status{position:absolute;z-index:2;left:36px;top:128px;display:flex;align-items:center;gap:22px}.hearts{display:flex;gap:3px}.heart{font-size:22px;color:#f69b8a;text-shadow:0 2px 6px #522d31;transition:.2s}.heart.empty{opacity:.3;filter:grayscale(1)}.crystal-count{display:flex;align-items:center;gap:5px;background:var(--glass);padding:7px 10px;border:1px solid #fff2;border-radius:8px;backdrop-filter:blur(9px)}.crystal-count span{color:#c5f3f0;font-size:19px}.crystal-count b{font:700 14px Outfit}.crystal-count small{font-size:8px;letter-spacing:.1em;color:#d9e3da}.hint{position:absolute;z-index:2;bottom:34px;left:50%;transform:translateX(-50%);border-radius:30px;background:rgba(17,34,36,.56);padding:11px 17px;font-size:12px;letter-spacing:.025em;white-space:nowrap;backdrop-filter:blur(10px);border:1px solid #fff2;color:#f1eddf;transition:opacity .5s}.hint span{color:var(--gold);margin-right:7px}.toast{position:absolute;z-index:6;left:50%;top:24%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;background:rgba(18,34,36,.82);border:1px solid #f8dda277;border-radius:30px;padding:12px 20px;font:600 13px Outfit,sans-serif;transition:.35s;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.controls-help{position:absolute;z-index:2;right:34px;bottom:27px;font-size:10px;color:#f2f1e4b5;display:flex;align-items:center;gap:6px}.controls-help kbd{border:1px solid #fff6;border-radius:4px;padding:3px 5px;background:#10252755;font:600 9px 'DM Sans';color:#fff}.start-screen,.win-screen{position:absolute;z-index:5;inset:0;display:flex;align-items:center;background:linear-gradient(90deg,rgba(12,29,33,.93) 0%,rgba(12,29,33,.84) 38%,rgba(12,29,33,.08) 80%);transition:opacity .8s,visibility .8s}.start-screen.hidden,.win-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.start-content{position:relative;margin-left:12%;width:min(440px,44vw);padding-top:2vh}.eyebrow{font-size:10px;letter-spacing:.3em;color:#f5d894;font-weight:700}.start-content h1{font:500 clamp(54px,7vw,92px)/.95 Outfit,sans-serif;letter-spacing:-.06em;margin:19px 0 17px;color:#f7f1df}.start-content h1 span{display:block;color:#d2dfa8;font-weight:400}.start-content p{color:#d0d6cb;font-size:15px;line-height:1.75;max-width:375px;margin:0 0 24px}.start-meta{display:flex;gap:17px;font-size:9px;letter-spacing:.13em;color:#e8e3cf;margin-bottom:29px}.start-meta span:first-letter{color:#ffdc91}.play-button{border:0;background:#f4d38b;color:#233336;padding:15px 19px;font:700 11px 'DM Sans';letter-spacing:.12em;border-radius:4px;box-shadow:0 8px 24px #e4c07822;cursor:pointer;transition:transform .2s,background .2s}.play-button:hover{transform:translateY(-2px);background:#ffe5a2}.play-button span{font-size:17px;margin-left:21px;vertical-align:-2px}.start-note{display:block;margin-top:18px;font-size:10px;color:#c1c9bd}.start-art{position:absolute;inset:0 0 0 37%;overflow:hidden;pointer-events:none}.sun-orb{position:absolute;right:24%;top:15%;width:115px;height:115px;background:#f8df9b;border-radius:50%;box-shadow:0 0 85px #eacb7566}.art-mountain{position:absolute;bottom:20%;width:80%;height:53%;clip-path:polygon(0 100%,45% 0,100% 100%);background:linear-gradient(130deg,#728b7d,#314c4e)}.m1{right:-2%;bottom:18%;transform:scale(1.2);opacity:.85}.m2{left:-8%;bottom:16%;transform:scale(.82);background:linear-gradient(120deg,#a4ae91,#5a7468)}.art-grass{position:absolute;bottom:0;left:0;right:0;height:26%;background:linear-gradient(0deg,#172e2c,#294c42);border-radius:50% 50% 0 0 / 14% 14% 0 0}.mobile-controls{display:none;position:absolute;z-index:3;inset:auto 0 max(24px,env(safe-area-inset-bottom));height:150px;pointer-events:none}.stick{position:absolute;left:max(25px,env(safe-area-inset-left));bottom:0;width:126px;height:126px;pointer-events:auto;touch-action:none}.stick-ring{position:absolute;inset:7px;border-radius:50%;background:#10282930;border:1px solid #ffffff58;backdrop-filter:blur(3px)}.stick-knob{position:absolute;left:50%;top:50%;width:51px;height:51px;transform:translate(-50%,-50%);border-radius:50%;background:#f0dfb8ad;border:1px solid #fff9;box-shadow:0 3px 15px #101f2038}.touch-btn{pointer-events:auto;position:absolute;bottom:6px;border:1px solid #fff8;border-radius:50%;color:#fff8e9;background:#1833318a;backdrop-filter:blur(7px);display:flex;align-items:center;justify-content:center;flex-direction:column;touch-action:none}.touch-btn span{font-size:25px}.touch-btn small{font:700 8px 'DM Sans';letter-spacing:.1em}.jump-btn{right:112px;width:62px;height:62px}.attack-btn{right:29px;width:78px;height:78px;background:#a7754a99}.loading{position:absolute;z-index:10;inset:0;display:grid;place-content:center;background:#142b31;color:#f2d794;font:600 12px Outfit;letter-spacing:.16em;transition:opacity .6s}.loading span{font-size:36px;text-align:center;margin-bottom:12px;animation:pulse 1.4s infinite}@keyframes pulse{50%{opacity:.3;transform:scale(.85}}.win-screen{justify-content:center;background:rgba(12,28,31,.74);backdrop-filter:blur(6px)}.win-card{text-align:center;width:min(420px,88vw);padding:40px 30px;background:rgba(21,43,42,.87);border:1px solid #f4da9c66;border-radius:14px;box-shadow:0 20px 70px #08191b88}.win-spark{font-size:42px;color:#ffe19b}.win-card h2{font:500 42px Outfit;margin:14px 0}.win-card p{color:#c9d4c8;line-height:1.7;font-size:14px;margin:0 auto 24px;max-width:300px}
@media(max-width:700px){.topbar{padding: max(14px,env(safe-area-inset-top)) 16px 0}.brand{gap:7px}.brand-mark{font-size:24px}.brand b{font-size:10px}.brand small{font-size:7px}.objective{top:68px;min-width:0;padding:8px 11px;gap:7px}.objective b{font-size:10px}.objective small{font-size:7px}.quest-icon{font-size:18px}.map-wrap{width:65px;height:65px;padding:4px}.status{top:88px;left:16px;gap:8px}.heart{font-size:17px}.crystal-count{padding:5px 7px}.crystal-count small{font-size:7px}.hint{bottom:165px;font-size:10px;max-width:88vw;overflow:hidden;text-overflow:ellipsis}.controls-help{display:none}.mobile-controls{display:block}.start-screen{align-items:flex-end;background:linear-gradient(0deg,rgba(12,29,33,.97) 0%,rgba(12,29,33,.82) 48%,rgba(12,29,33,.03) 100%)}.start-art{inset:0 0 37% 0}.sun-orb{width:75px;height:75px;right:23%;top:18%}.art-mountain{height:70%;bottom:1%}.m1{bottom:0}.m2{bottom:-5%}.art-grass{height:29%}.start-content{margin:0 auto 40px;width:88%;padding:0}.start-content h1{font-size:58px;margin:12px 0}.start-content p{font-size:13px;line-height:1.55;margin-bottom:17px}.start-meta{gap:11px;font-size:8px;margin-bottom:20px}.play-button{padding:14px 16px}.start-note{font-size:9px;margin-top:13px}.eyebrow{font-size:8px}.toast{top:28%;font-size:11px}.win-card h2{font-size:34px}}@media(orientation:landscape) and (max-height:500px){.start-content{margin-left:8%;width:43%;padding:0}.start-content h1{font-size:53px;margin:8px 0}.start-content p{font-size:12px;margin-bottom:13px}.start-meta{margin-bottom:13px}.start-note{margin-top:9px}.start-art{left:40%}.mobile-controls{height:125px}.stick{width:110px;height:110px}.hint{bottom:16px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const canvas=document.querySelector('#scene'),mapCanvas=document.querySelector('#map'),mapCtx=mapCanvas.getContext('2d');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9d8d1');scene.fog=new THREE.FogExp2('#a9d8d1',.0085);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.1,260);
scene.add(new THREE.HemisphereLight('#e5f6ef','#526746',2.1));
const sun=new THREE.DirectionalLight('#fff0cb',3.2);sun.position.set(-35,55,22);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-80;sun.shadow.camera.right=80;sun.shadow.camera.top=80;sun.shadow.camera.bottom=-80;sun.shadow.bias=-.0002;scene.add(sun);
const mats={};function mat(color,roughness=.9){return new THREE.MeshStandardMaterial({color,roughness})}
const grassMats=['#78a968','#83b176','#91b77a','#719f65'].map(c=>mat(c));
const water=new THREE.Mesh(new THREE.CircleGeometry(180,96),new THREE.MeshStandardMaterial({color:'#69b8bd',roughness:.27,metalness:.08,transparent:true,opacity:.94}));water.rotation.x=-Math.PI/2;water.position.y=-1.7;scene.add(water);
function hash(x,z){let v=Math.sin(x*127.1+z*311.7)*43758.5453;return v-Math.floor(v)}
function heightAt(x,z){const r=Math.hypot(x,z);const hills=1.2*Math.sin(x*.115+z*.04)+.9*Math.cos(z*.13-x*.06)+.48*Math.sin(x*.26)*Math.cos(z*.19);const radial=Math.max(0,1-Math.pow(r/72,4));return -1.35+Math.max(0,radial)*Math.max(0,2.1+hills)}
function makeTerrain(){const n=150,size=152,verts=[],colors=[],indices=[];const color=new THREE.Color();for(let iz=0;iz<=n;iz++)for(let ix=0;ix<=n;ix++){const x=(ix/n-.5)*size,z=(iz/n-.5)*size,y=heightAt(x,z);verts.push(x,y,z);let c=y<-.5?new THREE.Color('#c4b987'):y<.1?new THREE.Color('#a7b879'):new THREE.Color(['#82ad70','#8bb776','#76a566'][Math.floor(hash(ix,iz)*3)]);c.multiplyScalar(.94+hash(ix*4,iz*9)*.12);colors.push(c.r,c.g,c.b);if(ix<n&&iz<n){const a=iz*(n+1)+ix,b=a+1,d=a+n+1,e=d+1;indices.push(a,d,b,b,d,e)}}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.setIndex(indices);geo.computeVertexNormals();const mesh=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));mesh.receiveShadow=true;scene.add(mesh)}makeTerrain();
const trunkMat=mat('#76533b'),leafMats=['#477d59','#558c5c','#68965f','#3f7355'].map(c=>mat(c)),rockMat=mat('#858b78'),flowerMats=['#f0d48e','#f2a6a0','#d3c4ee'].map(c=>mat(c));
function addTree(x,z,s=1){const y=heightAt(x,z);if(y<-.1)return;const g=new THREE.Group();g.position.set(x,y,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.13*s,.24*s,1.65*s,6),trunkMat);trunk.position.y=.78*s;trunk.castShadow=true;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.DodecahedronGeometry((.72-i*.06)*s,0),leafMats[(Math.random()*leafMats.length)|0]);crown.position.set((Math.random()-.5)*.24*s,(1.48+i*.46)*s,(Math.random()-.5)*.2*s);crown.scale.set(1,1.12,1);crown.castShadow=true;g.add(crown)}scene.add(g)}
function addRock(x,z,s=1){const y=heightAt(x,z),rock=new THREE.Mesh(new THREE.DodecahedronGeometry(s,0),rockMat);rock.position.set(x,y+s*.42,z);rock.scale.set(1.25,.78,.9);rock.rotation.set(Math.random(),Math.random()*3,Math.random());rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}
for(let i=0;i<240;i++){const a=Math.random()*Math.PI*2,r=14+Math.sqrt(Math.random())*54,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x,z)<13||Math.hypot(x,z)>65)continue;if(Math.hypot(x-25,z+19)<12)continue;if(Math.random()<.73)addTree(x,z,.65+Math.random()*.75);else addRock(x,z,.35+Math.random()*.75)}
for(let i=0;i<170;i++){const a=Math.random()*6.28,r=5+Math.random()*55,x=Math.cos(a)*r,z=Math.sin(a)*r;if(heightAt(x,z)<.15)continue;const flower=new THREE.Mesh(new THREE.SphereGeometry(.09,6,5),flowerMats[(Math.random()*3)|0]);flower.position.set(x,heightAt(x,z)+.13,z);flower.scale.set(.7,1.3,.7);scene.add(flower)}
// A quiet stone circle marks the old shrine.
const shrine=new THREE.Group();shrine.position.set(25,heightAt(25,-19),-19);scene.add(shrine);
const plinth=new THREE.Mesh(new THREE.CylinderGeometry(3.35,3.8,.7,12),mat('#9a9274'));plinth.position.y=.3;plinth.receiveShadow=true;plinth.castShadow=true;shrine.add(plinth);
const inner=new THREE.Mesh(new THREE.CylinderGeometry(2.5,2.8,.25,12),mat('#b9a77a'));inner.position.y=.78;shrine.add(inner);
for(let i=0;i<7;i++){const a=i/7*Math.PI*2;const pillar=new THREE.Mesh(new THREE.BoxGeometry(.52,2.4,.58),mat('#8b927d'));pillar.position.set(Math.cos(a)*2.75,1.9,Math.sin(a)*2.75);pillar.rotation.y=-a;pillar.castShadow=true;shrine.add(pillar);const cap=new THREE.Mesh(new THREE.BoxGeometry(.7,.22,.72),mat('#b5a883'));cap.position.copy(pillar.position);cap.position.y+=1.24;cap.rotation.y=-a;shrine.add(cap)}
const ring=new THREE.Mesh(new THREE.TorusGeometry(1.08,.12,8,32),new THREE.MeshStandardMaterial({color:'#ffe5a1',emissive:'#ffbb58',emissiveIntensity:1.6,roughness:.3}));ring.position.set(0,2.4,0);shrine.add(ring);const core=new THREE.Mesh(new THREE.OctahedronGeometry(.63,1),new THREE.MeshStandardMaterial({color:'#fff4c2',emissive:'#ffd362',emissiveIntensity:1.8,roughness:.2}));core.position.y=2.4;shrine.add(core);
const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);
const tunic=mat('#3f7580'),skin=mat('#edc7a0'),hair=mat('#4b382d'),boots=mat('#5c4635'),capeMat=mat('#b45442'),gold=mat('#e6c47b');
function box(parent,w,h,d,m,x,y,z){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
const body=box(avatar,.68,.85,.4,tunic,0,1.15,0);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,12,10),skin);head.position.set(0,1.82,-.01);head.castShadow=true;avatar.add(head);const haircap=new THREE.Mesh(new THREE.SphereGeometry(.355,12,8,0,Math.PI*2,0,Math.PI*.56),hair);haircap.position.set(0,1.91,.015);avatar.add(haircap);const capTail=box(avatar,.22,.5,.18,mat('#d7bc77'),-.04,2.1,-.28);capTail.rotation.x=-.24;
box(avatar,.39,.2,.34,boots,-.19,.14,0);box(avatar,.39,.2,.34,boots,.19,.14,0);
const leftArm=box(avatar,.22,.58,.23,tunic,-.48,1.18,0);const rightArm=box(avatar,.22,.58,.23,tunic,.48,1.18,0);box(avatar,.48,.73,.11,capeMat,0,1.12,.28).rotation.x=-.12;
const sword=new THREE.Group();sword.position.set(.62,1.2,-.12);avatar.add(sword);const blade=box(sword,.11,.73,.1,mat('#d9e8dc',.32),0,.38,0);const cross=box(sword,.42,.09,.16,gold,0,.03,0);box(sword,.12,.27,.12,boots,0,-.15,0);sword.rotation.z=-.42;
const eyeMat=mat('#332b27');for(const x of [-.13,.13]){const e=new THREE.Mesh(new THREE.SphereGeometry(.035,6,6),eyeMat);e.position.set(x,1.84,-.32);avatar.add(e)}
// Crystals dotted along trails and clearings.
const pickups=[];const crystalMat=new THREE.MeshStandardMaterial({color:'#bff8e7',emissive:'#50cfc2',emissiveIntensity:1.05,roughness:.2,metalness:.12});
for(let i=0;i<14;i++){const a=i*2.399,r=8+(i%5)*7,x=Math.cos(a)*r,z=Math.sin(a)*r;if(Math.hypot(x-25,z+19)<9)continue;const y=heightAt(x,z);const g=new THREE.Group();g.position.set(x,y+.75,z);const c=new THREE.Mesh(new THREE.OctahedronGeometry(.43,0),crystalMat);c.scale.set(.75,1.55,.75);c.castShadow=true;g.add(c);const glow=new THREE.PointLight('#77e6ce',.65,4);glow.position.y=.25;g.add(glow);scene.add(g);pickups.push({group:g,baseY:y+.75,got:false})}
// Friendly-to-a-fault little moss slimes.
const enemies=[];const slimeMat=new THREE.MeshStandardMaterial({color:'#82ba79',roughness:.45});const slimeDark=mat('#3b654d');
for(const [x,z] of [[-17,-14],[17,14],[-29,19],[38,4],[5,37],[-43,-7]]){const g=new THREE.Group();g.position.set(x,heightAt(x,z),z);const blob=new THREE.Mesh(new THREE.SphereGeometry(.68,14,10),slimeMat);blob.scale.set(1.12,.72,1);blob.castShadow=true;g.add(blob);for(const ex of [-.2,.2]){const eye=new THREE.Mesh(new THREE.SphereGeometry(.075,8,6),mat('#f9efce'));eye.position.set(ex,.05,-.59);g.add(eye);const pupil=new THREE.Mesh(new THREE.SphereGeometry(.035,6,5),slimeDark);pupil.position.set(ex,.045,-.652);g.add(pupil)}scene.add(g);enemies.push({g,hp:2,phase:Math.random()*7,alive:true,home:new THREE.Vector3(x,0,z)})}
let started=false,won=false,health=5,shardCount=0,attackTime=0,attackCooldown=0,invuln=0,jumpV=0,onGround=true,elapsed=0;
const keys={};let joy={x:0,y:0};const heartsEl=document.querySelector('#hearts'),toastEl=document.querySelector('#toast');function drawHearts(){heartsEl.innerHTML='';for(let i=0;i<5;i++){const h=document.createElement('span');h.className='heart'+(i>=health?' empty':'');h.textContent='♥';heartsEl.appendChild(h)}}drawHearts();
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.classList.remove('show'),2100)}
function doAttack(){if(!started||attackCooldown>0)return;attackTime=.38;attackCooldown=.58;sword.rotation.z=-1.45;for(const e of enemies){if(!e.alive)continue;const dx=e.g.position.x-player.position.x,dz=e.g.position.z-player.position.z,dist=Math.hypot(dx,dz);const forward=new THREE.Vector3(0,0,-1).applyQuaternion(player.quaternion);const toward=new THREE.Vector3(dx,0,dz).normalize();if(dist<3.15&&forward.dot(toward)>.1){e.hp--;e.g.position.x+=toward.x*1.1;e.g.position.z+=toward.z*1.1;e.g.scale.setScalar(.78);setTimeout(()=>e.g.scale.setScalar(1),130);if(e.hp<=0){e.alive=false;scene.remove(e.g);toast('The mossling scampers off! +1 sunshard');shardCount++;document.querySelector('#shards').textContent=shardCount}}}}
function jump(){if(onGround&&started){jumpV=7.8;onGround=false}}
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')jump();if(e.code==='KeyF'||e.code==='KeyE')doAttack()});window.addEventListener('keyup',e=>keys[e.code]=false);
