  Line 48: const stick=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickId=null;stick.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(stickId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e)});function moveStick(e){const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=43,len=Math.hypot(dx,dy),scale=Math.min(1,max/(len||1));joy.x=dx*scale/max;joy.y=dy*scale/max;knob.style.transform=`translate(calc(-50% + ${joy.x*43}px),calc(-50% + ${joy.y*43}px))`}function endStick(e){if(e.pointerId!==stickId)return;stickId=null;joy={x:0,y:0};knob.style.transform='translate(-50%,-50%)'}stick.addEventListener('pointerup',endStick);stick.addEventListener('pointercancel',endStick);

